SELECT * FROM (SELECT time, MAX(CASE WHEN metric_name = 'metric_0001' THEN CAST(value AS DOUBLE PRECISION) END) AS value_1, MAX(CASE WHEN metric_name = 'metric_0002' THEN CAST(value AS DOUBLE PRECISION) END) AS value_2, MAX(CASE WHEN metric_name = 'metric_0003' THEN CAST(value AS DOUBLE PRECISION) END) AS value_3, MAX(CASE WHEN metric_name = 'metric_0004' THEN CAST(value AS DOUBLE PRECISION) END) AS value_4 FROM eav1000 WHERE metric_name IN ('metric_0001', 'metric_0002', 'metric_0003', 'metric_0004') GROUP BY time) s WHERE time = '2024-12-29 12:30:00'
